import{d as c,C as t,o as u,c as b,j as a,a as o,E as n,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第二章","description":"从美恶相待、有无相生，读到无为、不言与功成弗居。","frontmatter":{"title":"道德经第二章","description":"从美恶相待、有无相生，读到无为、不言与功成弗居。","category":"guide","aliases":["道德经第二章","老子第二章","dao de jing chapter 2"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-02.md","filePath":"daoism/dao-de-jing/chapter-02.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-02.md"},P=c({...m,setup(x){const i=[{id:"beauty-and-goodness",label:"天下皆知美之为美",showLabel:!0,sentences:[["天下皆知美之为美，斯",{text:"恶",glossary:"e"},"已。"],["皆知善之为善，斯不善已。"]],note:["【白话】天下人都知道怎样才算美，丑的分别也就随之显出了；都知道怎样才算善，不善的分别也随之显出了。","【王弼注择要】「美恶犹喜怒也，善不善犹是非也。喜怒同根，是非同门。」注从同根、相待说起，提醒人不能孤立地只看一端。","【读法】「恶」在这里与美相对，读 è，指丑。句子讨论分别与标举所带来的关系，不能直接推出美丑无别、善恶无须判断。"]},{id:"mutual-relations",label:"故有无相生",showLabel:!0,sentences:[["故有无相生，难易相成，长短",{text:"相形",glossary:"xiangxing"},"，"],["高下相倾，音声相和，前后相随。"]],note:["【白话】所以，有与无相互生成，难与易相互成就，长与短相互比较而显现，高与低相互倾依，音与声相互应和，前与后相互跟随。","【读法】六组关系把前文的美恶、善不善推展开来。「生、成、形、倾、和、随」各有侧重，不必全部压成一种对立关系；这里也没有断言任何事物都会自动变成其反面。"]},{id:"teaching-without-imposing",label:"是以圣人处无为之事",showLabel:!0,sentences:[["是以圣人处",{text:"无为",glossary:"wuwei"},"之事，行不言之教。"],["万物作焉而不辞，生而不有，为而不",{text:"恃",glossary:"shi"},"，功成而弗",{text:"居",glossary:"ju"},"。"]],note:["【白话】因此，圣人以不强作妄为的方式处事，施行不靠言说强加于人的教导。万物兴起而不加推拒，生养它们而不据为己有，有所作为而不自恃其力，事情成就而不占居功劳。","【王弼注择要】「因物而用，功自彼成，故不居也。」王弼把不居功连到事物自身的成就，而不是把一切归为施为者的独力。","【读法】「不有、不恃、弗居」都涉及行为之后怎样对待成果。无为仍可以有帮助和成就，关键是有没有强加、占有与自恃。"]},{id:"achievement-without-possession",label:"夫唯弗居，是以不去",showLabel:!0,sentences:[["夫唯弗居，是以不去。"]],note:["【白话】正因为不占居功劳，成就反而能够留存，不随个人的占有而消散。","【王弼注择要】「使功在己，则功不可久也。」注将持久与不把功劳系于一己相连。","【读法】这不是以退让换取更多名声的保证。若把不居功当成求功的手段，仍然绕回了以自己为中心的占有。"]}],r=[{id:"e",term:"恶",sense:2,pinyin:"è",context:"与「美」相对，指丑；与表示厌恶的 wù 区别。"},{id:"xiangxing",term:"相形",sense:1},{id:"wuwei",term:"无为",sense:1,context:"与不言之教、不占有和不居功连读，不作放任不管解。"},{id:"shi",term:"恃",sense:1},{id:"ju",term:"居",sense:1,context:"「功成而弗居」中指占居、据有功劳。"}];return(g,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第二章",tabindex:"-1"},[o("道德经第二章 "),a("a",{class:"header-anchor",href:"#道德经第二章","aria-label":'Permalink to "道德经第二章"'},"​")],-1)),n(s,{title:"分别如何成立，成就如何留存",summary:"本章先用美恶与六组相待关系松动孤立的判断，再转向圣人怎样处事。从「相生」读到「弗居」，要留意：成就不只来自一个施为者，也来自事物自身的条件。",points:[{label:"先读",text:"看美与恶、善与不善怎样相待而显。"},{label:"再辨",text:"六组关系为何引出无为与不言？"},{label:"后想",text:"做成一件事，为何还要说「弗居」？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[o("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),n(l,{sections:i,glossary:r,tone:"ink",density:"comfortable","aria-label":"《道德经》第二章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[o("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"皆知善之为善，斯不善已。",tone:"相待",guide:"善的名称并不孤立成立。读这里既要检查标举怎样制造分别，也要避免用关系性取消具体的是非判断。"},{text:"是以圣人处无为之事，行不言之教。",tone:"转折",guide:"「是以」把相待关系转到处事方式：若一味抬高一端、强加一个尺度，就可能激起另一端。圣人因而减少强作与说教。"},{text:"功成而弗居。夫唯弗居，是以不去。",tone:"落点",guide:"本章落在成果的归属。不居功承认事物与他人的作用，使成就不必依赖某个人反复申明自己的权力。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[o("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),n(h,{items:r}),e[4]||(e[4]=p("",15))])}}});export{_ as __pageData,P as default};
